 "content": "def transform(grid):
    out = [row[:] for row in grid]
    p1 = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    p2 = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2]
    if len(p1) != 1 or len(p2) != 1: return out
    (r,c),(tr,tc)=p1[0],p2[0]
    if tr == r:
        lo,hi=sorted((c,tc))
        for x in range(lo+1,hi): out[r][x]=3
    elif tc == c:
        lo,hi=sorted((r,tr))
        for y in range(lo+1,hi): out[y][c]=3
    else:
        # Diagonal staircase: diagonal from marker 1 toward marker 2, then continue
        # along the dominant axis until reaching the other marker's row or column.
        dr=(tr>r)-(tr<r); dc=(tc>c)-(tc<c)
        n=min(abs(tr-r),abs(tc-c))
        for _ in range(n):
            r+=dr; c+=dc
            if (r,c)!=(tr,tc): out[r][c]=3
        if abs(tr-r) > abs(tc-c):
            while r!=tr:
                r+=dr
                if (r,c)!=(tr,tc): out[r][c]=3
        else:
            while c!=tc:
                c+=dc
                if (r,c)!=(tr,tc): out[r][c]=3
    return out
