    (r,c),(s,t)=a[0],b[0]
    dr=(s>r)-(s<r); dc=(t>c)-(t<c)
    while r!=s and c!=t:
        r+=dr; c+=dc
        if (r,c)!=(s,t): out[r][c]=3
    if r==s:
